    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_1' => 'Sube el llamado a la acción de la tienda en línea o el descuento a una posición más alta de la página y repítelo cerca de la parte inferior del perfil o de la publicación del blog.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2' => 'Añade una llamada a la acción más clara en la principal vía de tráfico para que los visitantes lleguen a un destino de Forever en lugar de limitarse a contenido informativo.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2_source' => 'Para la fuente %s, prueba una llamada a la acción más clara que lleve a los usuarios directamente desde el contenido a la tienda web de Forever o al destino del descuento.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_3' => 'Revisa si los bloques del blog, las ventas y los descuentos hacen que el proceso de compra sea lo bastante visible y se repita con suficiente frecuencia.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.label' => 'Convierte los clics de la tienda en línea en registros o acciones de compra',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.text' => 'El colaborador ya tiene %s clics en la tienda web, pero todavía no ha conseguido registros durante este período.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_1' => 'Comprueba que el clic abra la URL de referencia correcta y lleve a la página o pantalla de la tienda en línea prevista sin errores.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_2' => 'Mejora el mensaje antes del clic: explica qué obtiene el visitante, por qué debería hacer clic ahora y qué ocurre después de entrar en la página de Forever.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3' => 'Prueba una ruta más sencilla para registrarse o comprar y elimina los pasos confusos después del primer clic.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3_country' => 'Si la mayor parte del tráfico proviene de %s, comprueba si el destino está localizado correctamente y abre la versión adecuada para ese mercado.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.label' => 'Aumentar la tasa de conversión mientras crece el tráfico',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.text' => 'El tráfico está creciendo un %s%%, pero la tasa de registro es de solo un %s%%, por lo que los clics adicionales aún no están generando suficientes resultados.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_1' => 'Mantén la fuente que está impulsando el crecimiento, pero ajusta el texto de la CTA y el mensaje introductorio para que permitan identificar mejor la intención de compra.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_2' => 'Genera confianza antes de la CTA: incluye un testimonio, un resultado, una minisección de preguntas frecuentes o una explicación clara de lo que ocurre después de hacer clic.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_3' => 'Compara las fuentes de clics y sigue dando prioridad únicamente a los canales que generan inscripciones o clientes potenciales de mayor calidad, no solo un mayor volumen de tráfico.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.label' => 'Aprovecha el interés existente para crear una ruta de ventas más sólida',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.text' => 'La aplicación ya está generando señales a través de WhatsApp (%1$s), productos (%2$s) e inscripciones (%3$s), pero eso todavía no está llevando a suficientes personas a la tienda.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_1' => 'Coloca una entrada principal clara a la tienda por encima de las demás opciones de venta.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_2' => 'Alinea el mensaje en el contenido, WhatsApp y los bloques de venta para que todos indiquen el mismo siguiente paso.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_3' => 'Conserva los bloques que generan interés, pero indica claramente dónde debe hacerse de inmediato el clic para comprar o registrarse.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.label' => 'Mantén el impulso con pequeñas optimizaciones',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.text' => 'El margen de crecimiento no es alto debido a un solo problema importante, sino a oportunidades de mejora menores.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_1' => 'Sigue dirigiendo el tráfico a los puntos de llamada a la acción más eficaces que ya funcionan bien.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_2' => 'Sigue probando el texto del titular, el orden de las CTA y los elementos de confianza para mantener o reducir la puntuación de oportunidad.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_3' => 'Sigue comprobando si los clics adicionales se convierten en registros, no solo en más tráfico.',
